package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.node.*;import com.ruoyi.medical.contracts.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
public class ConnectionVerificationSchemaTest {
 final PermissionSchema json=new PermissionSchema();final ConnectionVerificationSchema schema=new ConnectionVerificationSchema();final RuntimeGovernanceSchema local=new RuntimeGovernanceSchema();
 public ConnectionVerificationSchemaTest()throws Exception{}
 ObjectNode request(){String id="00000000-0000-4000-8000-000000000001",h="1".repeat(64);var n=json.object().put("schema_version","1.0.0").put("project_id",id).put("model_config_revision",id).put("purpose","MODEL_VERIFICATION").put("business_purpose","DOCUMENT_BODY").put("maximum_input_tokens","10").put("reason","fixture only");var basis=json.object().put("version_id",id).put("content_sha256",h);for(var field:java.util.List.of("scope_snapshot_basis","tokenizer_basis","role_basis","prompt_basis","enterprise_budget_basis","parent_budget_basis"))n.set(field,basis.deepCopy());n.set("rule_bases",json.object().arrayNode().add(basis));var coverage=json.object().put("selection_digest",h).put("delivered_digest",h).put("complete",true).putNull("next_cursor");n.set("exact_input",json.object().put("artifact_id",id).put("sha256",h).put("schema_ref","urn:fixture:1.0.0").set("coverage",coverage));var params=json.object().put("max_output_tokens",1).putNull("temperature").put("reasoning_effort","none").put("purpose","VERIFICATION");params.set("stop",json.object().arrayNode());n.set("request_parameters",params);return n;}
 byte[] bytes(ObjectNode n)throws Exception{return local.canonical(n).getBytes(java.nio.charset.StandardCharsets.UTF_8);}
 @Test void actualERequestRequiresBusinessPurposeSnapshotAndNonemptyRules()throws Exception{var valid=request();assertEquals(valid,schema.request(bytes(valid)));for(var field:java.util.List.of("business_purpose","scope_snapshot_basis")){var bad=valid.deepCopy();bad.remove(field);assertThrows(SchemaRejection.class,()->schema.request(bytes(bad)));}valid.set("rule_bases",json.object().arrayNode());assertThrows(SchemaRejection.class,()->schema.request(bytes(valid)));}
 @Test void duplicateFieldsAndOversizeOriginalAreRejected()throws Exception{assertThrows(java.io.IOException.class,()->schema.request("{\"schema_version\":\"1.0.0\",\"schema_version\":\"1.0.0\"}".getBytes()));assertThrows(SchemaRejection.class,()->schema.request(new byte[65537]));}
 @Test void deployedCapabilitiesAreExplicitAndKeyUsesOriginalAsciiContract()throws Exception{RuntimeGovernanceSchema.key("printable/?#key1234");assertThrows(SchemaRejection.class,()->RuntimeGovernanceSchema.key("bad key with space"));var n=json.object().put("schema_version","1.0.0").put("model_runtime_enabled",false).put("supported_model_scope","PROJECT");n.set("supported_providers",json.object().arrayNode().add("DEEPSEEK"));n.set("supported_reasoning_efforts",json.object().arrayNode().add("none"));n.set("current_context",json.object().put("tenant_id","00000000-0000-4000-8000-000000000001").put("context_revision","1").put("auth_epoch","1").put("governance_epoch","1"));local.validate("ModelRuntimeAvailability",n);n.put("supported_model_scope","ENTERPRISE");assertThrows(SchemaRejection.class,()->local.validate("ModelRuntimeAvailability",n));}
 public static void main(String[]args)throws Exception{var t=new ConnectionVerificationSchemaTest();t.actualERequestRequiresBusinessPurposeSnapshotAndNonemptyRules();t.duplicateFieldsAndOversizeOriginalAreRejected();t.deployedCapabilitiesAreExplicitAndKeyUsesOriginalAsciiContract();System.out.println("PASS 3 actual connection schema tests");}
}
